import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"QEMU debugging techniques","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/qemu-debugging.md","filePath":"troubleshooting/qemu-debugging.md"}'),i={name:"troubleshooting/qemu-debugging.md"};function n(d,e,r,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="qemu-debugging-techniques" tabindex="-1">QEMU debugging techniques <a class="header-anchor" href="#qemu-debugging-techniques" aria-label="Permalink to &quot;QEMU debugging techniques&quot;">​</a></h1><p>Capture everything, watch the machine (not just the guest), attach gdb, and know the errata — QEMU&#39;s own quirks account for a surprising share of &quot;OS bugs&quot;.</p><h2 id="capture-everything" tabindex="-1">Capture everything <a class="header-anchor" href="#capture-everything" aria-label="Permalink to &quot;Capture everything&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 -m 512 -cdrom build/opencube.iso \\</span></span>
<span class="line"><span>    -serial file:boot.log -display none \\</span></span>
<span class="line"><span>    -netdev user,id=n1 -device e1000,netdev=n1</span></span></code></pre></div><p>The serial log IS the boot narrative — one <code>OK</code> per subsystem, panic banners, register dumps, crashlog flushes. The serial console is <strong>authoritative</strong> (VGA is best-effort: the panic one-liner points you back to serial with <code>Registers and call trace on the serial console.</code>).</p><p>For a triple fault / reset loop:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-d int,cpu_reset,guest_errors -D qemu.log</span></span></code></pre></div><p>The log shows the last interrupt/reset; &quot;the last self-test line that did NOT print OK&quot; in boot.log names the stage that died.</p><h2 id="interactive-serial-monitor" tabindex="-1">Interactive serial + monitor <a class="header-anchor" href="#interactive-serial-monitor" aria-label="Permalink to &quot;Interactive serial + monitor&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 ... -serial stdio -monitor stdio</span></span></code></pre></div><p>gives the guest console and the QEMU monitor on one terminal (the E2E runner uses <code>mon:stdio</code>; commands prefixed <code>@</code> go to the monitor). To feed keystrokes a serial link cannot carry:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(qemu) sendkey ctrl-alt-f2      # OCSE GUI&lt;-&gt;CLI switch</span></span>
<span class="line"><span>(qemu) sendkey up               # menu navigation (PS/2 path)</span></span>
<span class="line"><span>(qemu) sendkey f2               # editor IME toggle</span></span>
<span class="line"><span>(qemu) screendump shot.ppm      # VGA proof (see errata first!)</span></span></code></pre></div><p><code>sendkey</code> is THE injection path for arrow/F-keys: CSI bytes over a TCP serial socket arrive too late at boot-menu time. Pointer input needs QMP <code>input-send-event</code> (HMP <code>mouse_move</code> is dead on <code>-display none</code> + QEMU 10).</p><h2 id="gdb-into-the-kernel" tabindex="-1">GDB into the kernel <a class="header-anchor" href="#gdb-into-the-kernel" aria-label="Permalink to &quot;GDB into the kernel&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 ... -s -S        # gdb stub, frozen at reset</span></span>
<span class="line"><span>gdb build/opencube_base.elf          # the pre-strip ELF has symbols</span></span>
<span class="line"><span>(gdb) target remote localhost:1234</span></span>
<span class="line"><span>(gdb) break kmain</span></span>
<span class="line"><span>(gdb) continue</span></span></code></pre></div><p><code>build/opencube_base.elf</code> is kept by <code>make kernel</code> precisely for this — the final <code>build/opencube.elf</code> is stripped.</p><h2 id="deterministic-replays" tabindex="-1">Deterministic replays <a class="header-anchor" href="#deterministic-replays" aria-label="Permalink to &quot;Deterministic replays&quot;">​</a></h2><p>The build is reproducible (<code>make reproducible-check</code>): the same tree produces byte-identical ELFs, so a crash you can reproduce twice is the same bytes both times. Combine with <code>-icount</code> for timing stability in network tests.</p><h2 id="the-qemu-errata-list" tabindex="-1">The QEMU errata list <a class="header-anchor" href="#the-qemu-errata-list" aria-label="Permalink to &quot;The QEMU errata list&quot;">​</a></h2><p>Quirks verified against this project — check these before blaming the kernel:</p><table tabindex="0"><thead><tr><th>Erratum</th><th>Effect</th><th>Workaround</th></tr></thead><tbody><tr><td>QEMU 10 <code>intel-hda</code> model dead-loops on 44.1 kHz</td><td>audio freeze at that rate (real hardware fine; documented in-source)</td><td>other rates, or <code>-device AC97</code>/<code>-device sb16</code></td></tr><tr><td>QEMU drops serial RX bytes right after an HMP <code>screendump</code></td><td>flaky input in the following seconds (verified with an in-kernel RX trace)</td><td>never screenshot mid-functional-round; re-run flapping checks isolated</td></tr><tr><td>HMP <code>mouse_move</code> dead on <code>-display none</code> + QEMU 10</td><td>GUI tests can&#39;t move the pointer</td><td>QMP <code>input-send-event</code></td></tr><tr><td>Serial echo overlaps guest output</td><td>the eaten-<code>e</code> <code>ega]</code> artifact; shifted fragments</td><td>tolerant matching (treat <code>[tag]</code> brackets as optional, strip the echo line); see <a href="./silent-failures.html">silent-failures.md</a> §8</td></tr><tr><td>TCG (no KVM) RSA-2048 &gt; 500 s</td><td>sshd first-boot keygen looks hung</td><td>pre-seed <code>etc.img</code> (<code>tools/host_keygen_etc.py</code>); generous timeouts (banner 420 s)</td></tr><tr><td>default <code>pc</code> machine has no Intel TCO</td><td><code>watchdog hw: none</code> (honest) — q35&#39;s ICH9-LPC has it</td><td><code>-machine q35</code> for TCO tests</td></tr><tr><td>user-net has no radio</td><td><code>wifi scan</code> honest no-radio</td><td>skip, or physical hardware</td></tr><tr><td>El Torito <code>-boot-info-table</code></td><td>zero-fills bytes 8..0x47 of the boot image — OCBL stage1 entry code destroyed (silent hang + 5 MB of 0x00 on serial)</td><td>never enable it for OCBL ISOs (<code>build_test_iso.py</code> deliberately omits it)</td></tr></tbody></table><h2 id="device-matrix-at-a-glance" tabindex="-1">Device matrix at a glance <a class="header-anchor" href="#device-matrix-at-a-glance" aria-label="Permalink to &quot;Device matrix at a glance&quot;">​</a></h2><p>The QEMU flags that light up each driver family are tabulated in the <a href="./../drivers/storage.html">driver manuals</a> — attach exactly the device you&#39;re debugging. The stock favorites:</p><ul><li><code>-device e1000,netdev=n1</code> + <code>-netdev user,id=n1</code> — best-tested NIC.</li><li><code>-device virtio-net-pci</code> — virtio paths (watch for TX timeouts).</li><li><code>-drive file=hd.img,format=raw</code> — disks; <code>readonly=on</code> produces the honest <code>virtio-blk: write rejected</code> (by design).</li><li><code>-device intel-hda</code> / <code>AC97</code> / <code>sb16</code> — audio.</li><li><code>-machine q35</code> — TCO watchdog, ICH9 LPC.</li></ul><h2 id="two-instance-links" tabindex="-1">Two-instance links <a class="header-anchor" href="#two-instance-links" aria-label="Permalink to &quot;Two-instance links&quot;">​</a></h2><p>Shared <code>-netdev socket,multicast=...</code> gives a real two-node link for the NIC/SSH tests; host-forwarding (<code>-netdev user,id=n1,hostfwd=tcp::2223-:22</code>) lets a host paramiko client reach the guest <code>sshd 22</code>.</p><h2 id="screenshot-pipelines" tabindex="-1">Screenshot pipelines <a class="header-anchor" href="#screenshot-pipelines" aria-label="Permalink to &quot;Screenshot pipelines&quot;">​</a></h2><p><code>make shot-bios</code> / <code>make shot-uefi</code> (VNC + monitor screendump → PNG via PIL, <code>tools/qemu_shot_vnc.py</code>); <code>tools/qemu_snap.py</code> boots an ISO, screendumps VGA, renders the 80×25 grid as ASCII. Screen-content assertions must check ≥ 2 colors and a measurable foreground ratio (BUG #66: never trust &quot;it rendered&quot; without a machine assertion).</p><h2 id="monitor-sockets-and-raw-serial" tabindex="-1">Monitor sockets and raw serial <a class="header-anchor" href="#monitor-sockets-and-raw-serial" aria-label="Permalink to &quot;Monitor sockets and raw serial&quot;">​</a></h2><p>For scripted control, put the monitor and serial on unix sockets:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 ... \\</span></span>
<span class="line"><span>    -serial unix:serial.sock,server,nowait \\</span></span>
<span class="line"><span>    -monitor unix:mon.sock,server,nowait</span></span></code></pre></div><ul><li>Raw control bytes (the <code>fix1_before_*</code> captures) need a unix-socket chardev so bytes arrive <strong>verbatim</strong> — a TCP serial link mangles timing and eats characters at boot-menu time.</li><li><code>socat - UNIX-CONNECT:mon.sock</code> gives you the monitor; <code>sendkey</code>, <code>screendump</code>, <code>pmemsave</code>, device hot-add all work there.</li><li>Memory dump for post-mortems: <code>(qemu) pmemsave 0xb8000 4000 vga.bin</code> (the VGA text cells — how the OCIRE scroll proofs work, no OCR needed).</li><li>Device triage from the monitor: <code>info pci</code>, <code>info block</code>, <code>info usb</code>; hot-add/remove to bisect a probe failure without rebooting the host.</li></ul><h2 id="sendkey-cookbook" tabindex="-1">sendkey cookbook <a class="header-anchor" href="#sendkey-cookbook" aria-label="Permalink to &quot;sendkey cookbook&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(qemu) sendkey up            # OCBL menu: entry up (also serial CSI ESC[A)</span></span>
<span class="line"><span>(qemu) sendkey down           # entry down</span></span>
<span class="line"><span>(qemu) sendkey ret            # select</span></span>
<span class="line"><span>(qemu) sendkey f2             # editor IME toggle / TUI save-config</span></span>
<span class="line"><span>(qemu) sendkey f5             # TUI repaint</span></span>
<span class="line"><span>(qemu) sendkey esc            # leave a TUI page</span></span>
<span class="line"><span>(qemu) sendkey ctrl-alt-f1    # OCSE GUI &lt;-&gt; CLI switch</span></span>
<span class="line"><span>(qemu) sendkey ctrl-alt-f2    # the other direction</span></span></code></pre></div><p>Rules: PS/2 is THE injection path (CSI bytes over serial arrive too late at menu time); compose keys with dashes (<code>ctrl-alt-f2</code>); the OCBL menu itself understands only Up/Down/Enter by contract, plus the serial CSI mirror for headless automation.</p><h2 id="reading-boot-log-—-a-worked-example" tabindex="-1">Reading boot.log — a worked example <a class="header-anchor" href="#reading-boot-log-—-a-worked-example" aria-label="Permalink to &quot;Reading boot.log — a worked example&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[    0.000] BOOT: OK</span></span>
<span class="line"><span>[    0.412] KM_AIN_ENTERED: OK</span></span>
<span class="line"><span>[    1.208] SCHED_READY: OK</span></span>
<span class="line"><span>[    2.017] DRIVERS_READY: FAIL      &lt;-- died here</span></span></code></pre></div><p>The FAIL line names the stage; the last driver line above it names the device. Cross-reference the stage ladder in <a href="./boot-failures.html">boot-failures.md</a> §1; the OCBL side judged this boot against the same stages (30 s boot / 10 s phase budgets, ≥ 8 s RTC silence = failure). A panic banner in the same log means the kernel recovered a record — check <code>crashlog</code> on the next boot.</p><h2 id="determinism-and-reproducibility" tabindex="-1">Determinism and reproducibility <a class="header-anchor" href="#determinism-and-reproducibility" aria-label="Permalink to &quot;Determinism and reproducibility&quot;">​</a></h2><ul><li><code>make reproducible-check</code> verifies byte-identical outputs.</li><li>Same tree + same flags = same crash: bisect by build, not by guess.</li><li><code>-icount</code> for timing-stable network rounds (the TCP suites rely on it); pair with <code>-rtc base=utc</code> for sane clock-dependent tests (X509_E_EXPIRED / NOT_YET are the trap otherwise).</li></ul><h2 id="make-targets-that-drive-qemu-for-you" tabindex="-1">Make targets that drive QEMU for you <a class="header-anchor" href="#make-targets-that-drive-qemu-for-you" aria-label="Permalink to &quot;Make targets that drive QEMU for you&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Target</th><th>What it does</th></tr></thead><tbody><tr><td><code>make run-bios</code> / <code>run-uefi</code></td><td>boot the ISO with serial stdio (BIOS / OVMF)</td></tr><tr><td><code>make run-bios-gui</code> / <code>run-uefi-gui</code></td><td>GTK window so the PS/2 keyboard gets real scancodes</td></tr><tr><td><code>make run-bios-persist</code> / <code>run-uefi-persist</code></td><td><code>-snapshot</code> OFF so /etc edits persist in <code>build/etc.img</code></td></tr><tr><td><code>make shot-bios</code> / <code>shot-uefi</code></td><td>VNC + monitor screendump → PNG (<code>tools/qemu_shot_vnc.py</code>)</td></tr></tbody></table><p>All of them assume <code>build/opencube.iso</code> exists (<code>make iso</code>).</p><h2 id="what-to-capture-for-a-bug-report" tabindex="-1">What to capture for a bug report <a class="header-anchor" href="#what-to-capture-for-a-bug-report" aria-label="Permalink to &quot;What to capture for a bug report&quot;">​</a></h2><ol><li><code>boot.log</code> (full <code>-serial file:</code> capture of the session).</li><li><code>qemu.log</code> if <code>-d int,cpu_reset</code> was on.</li><li>The exact QEMU command line and <code>-version</code>.</li><li>In-guest, when possible: <code>health</code>, <code>dmesg 1024</code>, <code>crashlog</code>, <code>dumpinfo</code>, <code>abcfg</code> (A/B state), <code>update status</code>.</li></ol><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./boot-failures.html">boot-failures.md</a> — reading the boot narrative</li><li><a href="./silent-failures.html">silent-failures.md</a> — serial-echo tolerance, capture routing</li><li><a href="./../dev/qemu-testing.html">../dev/qemu-testing.md</a> — the full test tooling</li><li><a href="./../dev/debugging.html">../dev/debugging.md</a> — developer techniques</li></ul>`,47)])])}const m=t(i,[["render",n]]);export{u as __pageData,m as default};
